"""Пользователь библиотеки и роли."""

from django.contrib.auth.base_user import AbstractBaseUser, BaseUserManager
from django.contrib.auth.models import PermissionsMixin
from django.db import models


class UserManager(BaseUserManager):
    """Менеджер пользователей, где логин — email."""

    use_in_migrations = True

    def create_user(self, email, password=None, **extra_fields):
        if not email:
            raise ValueError("Email обязателен")
        email = self.normalize_email(email)
        user = self.model(email=email, **extra_fields)
        user.set_password(password)
        user.save(using=self._db)
        return user

    def create_superuser(self, email, password=None, **extra_fields):
        extra_fields.setdefault("role", User.Role.ADMIN)
        extra_fields.setdefault("is_staff", True)
        extra_fields.setdefault("is_superuser", True)
        extra_fields.setdefault("is_active", True)

        if extra_fields["role"] != User.Role.ADMIN:
            raise ValueError("Суперпользователь должен иметь роль admin")
        return self.create_user(email, password, **extra_fields)


class User(AbstractBaseUser, PermissionsMixin):
    """Пользователь системы: читатель, библиотекарь или администратор."""

    class Role(models.TextChoices):
        READER = "reader", "Читатель"
        LIBRARIAN = "librarian", "Библиотекарь"
        ADMIN = "admin", "Администратор"

    email = models.EmailField("Email", unique=True)
    full_name = models.CharField("ФИО", max_length=150)
    phone = models.CharField("Телефон", max_length=20, blank=True)
    role = models.CharField(
        "Роль", max_length=20, choices=Role.choices, default=Role.READER
    )
    is_active = models.BooleanField("Активен", default=True)
    is_staff = models.BooleanField("Доступ в админку", default=False)
    date_joined = models.DateTimeField("Дата регистрации", auto_now_add=True)

    objects = UserManager()

    USERNAME_FIELD = "email"
    REQUIRED_FIELDS = ["full_name"]

    class Meta:
        verbose_name = "Пользователь"
        verbose_name_plural = "Пользователи"
        ordering = ["-date_joined"]

    def __str__(self):
        return f"{self.full_name} <{self.email}>"

    @property
    def is_admin(self):
        return self.role == self.Role.ADMIN

    @property
    def is_librarian(self):
        return self.role in (self.Role.LIBRARIAN, self.Role.ADMIN)

"""Разрешения по ролям.

Права проверяются только на backend: frontend лишь скрывает разделы.
"""

from rest_framework.permissions import BasePermission

from users.models import User


class IsAdmin(BasePermission):
    """Только администратор."""

    message = "Действие доступно только администратору"

    def has_permission(self, request, view):
        return bool(
            request.user
            and request.user.is_authenticated
            and request.user.role == User.Role.ADMIN
        )


class IsLibrarian(BasePermission):
    """Библиотекарь или администратор."""

    message = "Действие доступно только библиотекарю"

    def has_permission(self, request, view):
        return bool(
            request.user
            and request.user.is_authenticated
            and request.user.role in (User.Role.LIBRARIAN, User.Role.ADMIN)
        )


class IsOwnerOrStaff(BasePermission):
    """Владелец объекта или сотрудник (библиотекарь/администратор).

    Для моделей с полем reader. Имя поля владельца можно переопределить
    атрибутом owner_field у view.
    """

    message = "Нет доступа к чужому объекту"

    def has_object_permission(self, request, view, obj):
        user = request.user
        if not user or not user.is_authenticated:
            return False
        if user.role in (User.Role.LIBRARIAN, User.Role.ADMIN):
            return True

        owner_field = getattr(view, "owner_field", "reader")
        owner_id = getattr(obj, f"{owner_field}_id", None)
        return owner_id == user.id

