import axios from "axios";

const ACCESS_KEY = "library.access";
const REFRESH_KEY = "library.refresh";

export const tokenStorage = {
  getAccess: () => localStorage.getItem(ACCESS_KEY),
  getRefresh: () => localStorage.getItem(REFRESH_KEY),
  set({access, refresh}) {...},
  clear() {...},
};

export const api = axios.create({ baseURL: import.meta.env.VITE_API_URL || "http://127.0.0.1:8000/api", headers: {"Content-Type": "application/json"} });

let refreshPromise = null;
let authFailureHandler = null;
export function setAuthFailureHandler(fn) { authFailureHandler = fn; }

api.interceptors.request.use(config => { const token = tokenStorage.getAccess(); if (token && !config.skipAuth) config.headers.Authorization = `Bearer ${token}`; return config; });

async function refreshAccessToken() {
  const refresh = tokenStorage.getRefresh();
  if (!refresh) throw new Error("no refresh");
  const { data } = await axios.post(`${api.defaults.baseURL}/auth/refresh/`, { refresh });
  tokenStorage.setAccess(data.access);
  return data.access;
}

api.interceptors.response.use(r => r, async error => {
  const { response, config } = error;
  if (!response || response.status !== 401 || config._retry || config.url.includes("/auth/login/") || config.url.includes("/auth/refresh/") || config.url.includes("/auth/register/")) {
    return Promise.reject(error);
  }
  config._retry = true;
  try {
    refreshPromise = refreshPromise || refreshAccessToken().finally(() => { refreshPromise = null; });
    const access = await refreshPromise;
    config.headers.Authorization = `Bearer ${access}`;
    return api(config);
  } catch (refreshError) {
    tokenStorage.clear();
    if (authFailureHandler) authFailureHandler();
    return Promise.reject(refreshError);
  }
});

Careful: `refreshPromise` reset before awaiting: use const promise = refreshPromise || ...; refreshPromise = promise; then await. My code above sets refreshPromise then finally nulls; but awaiting `refreshPromise` after assignment works. However `.finally` returns new promise stored? `refreshPromise = refreshPromise || refreshAccessToken().finally(...)` fine.

Hmm in catch, we need to know whether original 401 was from login (don't attempt refresh). Check url includes "/auth/login/" etc.

