const AuthContext = createContext(null);
export function AuthProvider({children}) {
  const [user, setUser] = useState(null);
  const [initializing, setInitializing] = useState(true);

  const clearAuth = useCallback(() => { tokenStorage.clear(); setUser(null); }, []);

  useEffect(() => {
    setAuthFailureHandler(() => setUser(null));
    let active = true;
    async function loadUser() {
      if (!tokenStorage.getAccess() && !tokenStorage.getRefresh()) { setInitializing(false); return; }
      try { const {data} = await api.get("/auth/me/"); if (active) setUser(data); }
      catch { tokenStorage.clear(); if(active) setUser(null); }
      finally { if(active) setInitializing(false); }
    }
    loadUser();
    return () => { active = false; setAuthFailureHandler(null); };
  }, []);

  login = async (email, password) => { const {data} = await api.post("/auth/login/", {email,password}); tokenStorage.set(data); setUser(data.user); return data.user; }
  register = async (payload) => { await api.post("/auth/register/", payload); return login(payload.email, payload.password); }
  logout = async () => { const refresh = tokenStorage.getRefresh(); try { if (refresh) await api.post("/auth/logout/", {refresh}); } finally { clearAuth(); } }

  value memo.
}

