import { createContext, useCallback, useContext, useEffect, useMemo, useState } from "react";

import { api, setAuthFailureHandler, tokenStorage } from "../api/client";

const AuthContext = createContext(null);

/**
 * Состояние авторизации: пользователь, вход, регистрация, выход.
 * Запросы к API собраны здесь, страницы только вызывают методы.
 */
export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [initializing, setInitializing] = useState(true);

  const clearSession = useCallback(() => {
    tokenStorage.clear();
    setUser(null);
  }, []);

  // Сбой обновления токена в api/client.js означает конец сессии.
  useEffect(() => {
    setAuthFailureHandler(clearSession);
    return () => setAuthFailureHandler(null);
  }, [clearSession]);

  // При старте восстанавливаем пользователя по сохранённому access-токену.
  useEffect(() => {
    let cancelled = false;

    async function restoreSession() {
      if (!tokenStorage.getAccess()) {
        setInitializing(false);
        return;
      }
      try {
        const { data } = await api.get("/auth/me/");
        if (!cancelled) setUser(data);
      } catch {
        if (!cancelled) clearSession();
      } finally {
        if (!cancelled) setInitializing(false);
      }
    }

    restoreSession();
    return () => {
      cancelled = true;
    };
  }, [clearSession]);

  const login = useCallback(async ({ email, password }) => {
    const { data } = await api.post("/auth/login/", { email, password });
    tokenStorage.save({ access: data.access, refresh: data.refresh });
    setUser(data.user);
    return data.user;
  }, []);

  const register = useCallback(
    async (payload) => {
      await api.post("/auth/register/", payload);
      // Backend при регистрации не выдаёт токены — входим сразу после создания.
      return login({ email: payload.email, password: payload.password });
    },
    [login],
  );

  const logout = useCallback(async () => {
    const refresh = tokenStorage.getRefresh();
    try {
      if (refresh) {
        await api.post("/auth/logout/", { refresh });
      }
    } catch {
      // Даже если backend недоступен, локальную сессию закрываем.
    } finally {
      clearSession();
    }
  }, [clearSession]);

  const value = useMemo(
    () => ({ user, initializing, login, register, logout }),
    [user, initializing, login, register, logout],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth должен использоваться внутри AuthProvider");
  }
  return context;
}

/** Подписи ролей для интерфейса. */
export const ROLE_LABELS = {
  reader: "Читатель",
  librarian: "Библиотекарь",
  admin: "Администратор",
};

export function getRoleLabel(role) {
  return ROLE_LABELS[role] || role || "—";
}

import { Navigate, Outlet, useLocation } from "react-router-dom";

import Loader from "../components/Loader";
import { useAuth } from "./AuthContext";

/** Пускает только авторизованных; запоминает адрес, куда пользователь шёл. */
export function ProtectedRoute() {
  const { user, initializing } = useAuth();
  const location = useLocation();

  if (initializing) {
    return <Loader full height="page" text="Проверяем авторизацию…" />;
  }

  if (!user) {
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  return <Outlet />;
}

/** Страницы входа и регистрации: авторизованному здесь делать нечего. */
export function PublicOnlyRoute() {
  const { user, initializing } = useAuth();

  if (initializing) {
    return <Loader full height="page" text="Проверяем авторизацию…" />;
  }

  if (user) {
    return <Navigate to="/" replace />;
  }

  return <Outlet />;
}

/** Индикатор загрузки: строчный или на весь экран. */
export default function Loader({ text = "Загрузка…", full = false, height = "block" }) {
  const className = [
    "loader",
    full ? "loader--full" : "",
    height === "page" ? "loader--page" : "",
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <div className={className} role="status" aria-live="polite">
      <span className="loader__spinner" aria-hidden="true" />
      <span className="loader__text">{text}</span>
    </div>
  );
}

/** Сообщение об ошибке с необязательной кнопкой повтора. */
export default function ErrorMessage({ message, onRetry, retryLabel = "Повторить" }) {
  if (!message) return null;

  return (
    <div className="alert alert--error" role="alert">
      <span className="alert__text">{message}</span>
      {onRetry && (
        <button type="button" className="alert__retry" onClick={onRetry}>
          {retryLabel}
        </button>
      )}
    </div>
  );
}

import { useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";

import { getErrorMessage, getFieldErrors } from "../api/client";
import { useAuth } from "../auth/AuthContext";
import AuthLayout from "../components/AuthLayout";
import ErrorMessage from "../components/ErrorMessage";

const EMPTY_FORM = { email: "", password: "" };

export default function LoginPage() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  const [form, setForm] = useState(EMPTY_FORM);
  const [fieldErrors, setFieldErrors] = useState({});
  const [generalError, setGeneralError] = useState("");
  const [submitting, setSubmitting] = useState(false);

  const redirectTo = location.state?.from?.pathname || "/";

  function handleChange(event) {
    const { name, value } = event.target;
    setForm((prev) => ({ ...prev, [name]: value }));
    setFieldErrors((prev) => ({ ...prev, [name]: "" }));
  }

  async function handleSubmit(event) {
    event.preventDefault();
    setGeneralError("");

    if (!form.email.trim() || !form.password) {
      setFieldErrors({
        email: form.email.trim() ? "" : "Введите email",
        password: form.password ? "" : "Введите пароль",
      });
      return;
    }

    setSubmitting(true);
    try {
      await login({ email: form.email.trim(), password: form.password });
      navigate(redirectTo, { replace: true });
    } catch (error) {
      const errors = getFieldErrors(error);
      setFieldErrors(errors);
      setGeneralError(
        Object.keys(errors).length ? "" : getErrorMessage(error, "Не удалось войти."),
      );
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <AuthLayout
      title="Вход"
      subtitle="Войдите, чтобы бронировать книги и следить за очередью."
      footer={
        <span>
          Нет аккаунта?{" "}
          <Link className="link" to="/register">
            Зарегистрироваться
          </Link>
        </span>
      }
    >
      <ErrorMessage message={generalError} />

      <form className="form" onSubmit={handleSubmit} noValidate>
        <div className="field">
          <label className="field__label" htmlFor="login-email">
            Email
          </label>
          <input
            id="login-email"
            className={`input${fieldErrors.email ? " input--invalid" : ""}`}
            type="email"
            name="email"
            autoComplete="email"
            placeholder="reader1@library.local"
            value={form.email}
            onChange={handleChange}
            disabled={submitting}
            aria-invalid={Boolean(fieldErrors.email)}
          />
          {fieldErrors.email && <p className="field__error">{fieldErrors.email}</p>}
        </div>

        <div className="field">
          <label className="field__label" htmlFor="login-password">
            Пароль
          </label>
          <input
            id="login-password"
            className={`input${fieldErrors.password ? " input--invalid" : ""}`}
            type="password"
            name="password"
            autoComplete="current-password"
            placeholder="••••••••"
            value={form.password}
            onChange={handleChange}
            disabled={submitting}
            aria-invalid={Boolean(fieldErrors.password)}
          />
          {fieldErrors.password && <p className="field__error">{fieldErrors.password}</p>}
        </div>

        {fieldErrors.non_field_errors && (
          <p className="field__error">{fieldErrors.non_field_errors}</p>
        )}

        <button className="button button--primary button--block" type="submit" disabled={submitting}>
          {submitting ? "Вход…" : "Войти"}
        </button>
      </form>
    </AuthLayout>
  );
}

