async function waitFor(expression, label, timeout=20000) {
  const started = Date.now();
  while (Date.now()-started < timeout) {
    const v = await evalJs(expression).catch(()=>false);
    if (v) return v;
    await sleep(150);
  }
  const dump = await evalJs("document.body.innerText.slice(0,500)").catch(()=> "?");
  throw new Error(`timeout: ${label}; body: ${dump}`);
}
