const API = "http://127.0.0.1:8000/api";
const PASSWORD = "demo12345";

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const results = [];

function check(name, ok, extra = "") {
  results.push({ name, ok });
  console.log(`${ok ? "PASS" : "FAIL"}  ${name}${extra ? ` — ${extra}` : ""}`);
  if (!ok) process.exitCode = 1;
}

async function waitForHttp(url, timeout = 30000) {
  const started = Date.now();
  while (Date.now() - started < timeout) {
    try {
      await fetch(url);
      return;
    } catch {
      await sleep(300);
    }
  }
  throw new Error(`service not reachable: ${url}`);
}

async function newTarget() {
  const response = await fetch(
    `http://127.0.0.1:${CDP_PORT}/json/new?${encodeURIComponent("about:blank")}`,
    { method: "PUT" },
  );
  return response.json();
}

function connect(url) {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(url);
    ws.addEventListener("open", () => resolve(ws), { once: true });
    ws.addEventListener("error", reject, { once: true });
  });
}

async function main() {
  await waitForHttp(`http://127.0.0.1:${CDP_PORT}/json/version`);
  await waitForHttp(`${API}/auth/me/`).catch(() => {});
  await sleep(1500);

  const target = await newTarget();
  const ws = await connect(target.webSocketDebuggerUrl);

  let lastId = 0;
  const pending = new Map();
  ws.addEventListener("message", (event) => {
    const message = JSON.parse(event.data);
    if (message.id && pending.has(message.id)) {
      const { resolve, reject } = pending.get(message.id);
      pending.delete(message.id);
      if (message.error) reject(new Error(JSON.stringify(message.error)));
      else resolve(message.result);
    }
  });

  function send(method, params = {}) {
    const id = ++lastId;
    ws.send(JSON.stringify({ id, method, params }));
    return new Promise((resolve, reject) => pending.set(id, { resolve, reject }));
  }

  async function evalJs(expression) {
    const response = await send("Runtime.evaluate", {
      expression,
      returnByValue: true,
      awaitPromise: true,
      userGesture: true,
    });
    if (response.exceptionDetails) {
      throw new Error(response.exceptionDetails.exception?.description || "evaluate failed");
    }
    return response.result.value;
  }

  async function waitFor(expression, label, timeout = 20000) {
    const started = Date.now();
    while (Date.now() - started < timeout) {
      const value = await evalJs(expression).catch(() => false);
      if (value) return value;
      await sleep(150);
    }
    const body = await evalJs("document.body.innerText.slice(0, 400)").catch(() => "?");
    throw new Error(`timeout: ${label}; page: ${body}`);
  }

  async function navigate(url) {
    await send("Page.navigate", { url });
    await waitFor("document.readyState === 'complete'", `load ${url}`);
    await waitFor("document.getElementById('root')?.children.length > 0", `render ${url}`);
  }

  await send("Page.enable");
  await send("Runtime.enable");

  const FILL = `
    function fill(selector, value) {
      const input = document.querySelector(selector);
      if (!input) throw new Error('no input ' + selector);
      const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set;
      setter.call(input, value);
      input.dispatchEvent(new Event('input', { bubbles: true }));
      return input.value;
    }
  `;

  // 1. Protected page without token redirects to login.
  await navigate(`${APP}/`);
  await waitFor("location.pathname === '/login'", "redirect to /login");
  const heading = await evalJs("document.querySelector('h1')?.textContent");
  check("Гость с / попадает на /login", true, `h1="${heading}"`);
  check("Страница входа отрисована", heading === "Вход");

  // 2. Wrong password shows a clear error.
  await evalJs(`${FILL}; fill('#login-email', 'reader1@library.local'); fill('#login-password', 'wrong-pass'); document.querySelector('form').requestSubmit();`);
  const loginError = await waitFor("document.querySelector('.alert--error')?.textContent", "login error");
  check("Неверный пароль показывает ошибку", loginError.includes("Неверный email или пароль"), loginError.trim());

  // 3. Successful login.
  await evalJs(`${FILL}; fill('#login-email', 'reader1@library.local'); fill('#login-password', '${PASSWORD}'); document.querySelector('form').requestSubmit();`);
  await waitFor("location.pathname === '/' && !!document.querySelector('.home__title')", "login redirect");
  const greeting = await evalJs("document.querySelector('.home__title')?.textContent");
  check("Вход читателя работает", greeting.includes("Читатель 1"), greeting);
  const tokensAfterLogin = await evalJs("JSON.stringify({ access: localStorage.getItem('library.access'), refresh: localStorage.getItem('library.refresh') })");
  const tokens = JSON.parse(tokensAfterLogin);
  check(
    "Токены сохранены в localStorage",
    Boolean(tokens.access && tokens.refresh),
    `access=${tokens.access ? "есть" : "нет"}, refresh=${tokens.refresh ? "есть" : "нет"}`,
  );

  // 4. Session survives a reload.
  await send("Page.reload");
  await waitFor("document.readyState === 'complete'", "reload");
  await waitFor("!!document.querySelector('.home__title')", "session restore");
  const pathAfterReload = await evalJs("location.pathname");
  check("Сессия сохраняется после перезагрузки", pathAfterReload === "/", `path=${pathAfterReload}`);

  // 5. Logout clears the session and revokes the refresh token.
  await evalJs("document.querySelector('.home__account button').click()");
  await waitFor("location.pathname === '/login'", "logout redirect");
  const storedAfterLogout = await evalJs("JSON.stringify({ access: localStorage.getItem('library.access'), refresh: localStorage.getItem('library.refresh') })");
  check("Выход очищает localStorage", storedAfterLogout === '{"access":null,"refresh":null}', storedAfterLogout);

  const refreshAttempt = await fetch(`${API}/auth/refresh/`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ refresh: tokens.refresh }),
  });
  check("Refresh после выхода отклонён", refreshAttempt.status === 401, `status=${refreshAttempt.status}`);

  // 6. Protected page again requires login.
  await navigate(`${APP}/`);
  await waitFor("location.pathname === '/login'", "second redirect");
  check("После выхода закрытая страница недоступна", true);

  // 7. Registration creates a reader and signs in immediately.
  await evalJs("document.querySelector('a[href=\"/register\"]').click()");
  await waitFor("location.pathname === '/register'", "go to register");
  const email = `e2e${Date.now()}@library.local`;
  await evalJs(
    `${FILL}; fill('#register-name', 'E2E Читатель'); fill('#register-email', '${email}'); fill('#register-phone', '+7 900 111-22-33'); fill('#register-password', 'StrongPass123!'); fill('#register-password2', 'StrongPass123!'); document.querySelector('form').requestSubmit();`,
  );
  await waitFor("location.pathname === '/' && !!document.querySelector('.home__title')", "register redirect", 25000);
  const registerGreeting = await evalJs("document.querySelector('.home__title')?.textContent");
  const registerRole = await evalJs("document.querySelectorAll('.home__detail dd')[1]?.textContent");
  const registerTokens = await evalJs("Boolean(localStorage.getItem('library.access'))");
  check("Регистрация работает и сразу входит", registerGreeting.includes("E2E Читатель"), registerGreeting);
  check("Новый пользователь — читатель", registerRole === "Читатель", registerRole);
  check("После регистрации есть токены", registerTokens === true);

  // 8. Authorized user is redirected away from /login.
  await navigate(`${APP}/login`);
  await waitFor("location.pathname === '/'", "redirect authorized from /login");
  check("Авторизованный не попадает на /login", true);

  ws.close();
  await fetch(`http://127.0.0.1:${CDP_PORT}/json/close/${target.id}`);

  const failed = results.filter((item) => !item.ok).length;
  console.log(`\n${results.length - failed}/${results.length} проверок пройдено`);
  process.exit(failed ? 1 : 0);
}

main().catch((error) => {
  console.error("ERROR:", error.message);
  process.exit(1);
});

const CDP_PORT = 9222;
const APP = "http://localhost:5173";
const API = "http://127.0.0.1:8000/api";

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
let failed = 0;

function check(name, ok, extra = "") {
  if (!ok) failed += 1;
  console.log(`${ok ? "PASS" : "FAIL"}  ${name}${extra ? ` — ${extra}` : ""}`);
}

function connect(url) {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(url);
    ws.addEventListener("open", () => resolve(ws), { once: true });
    ws.addEventListener("error", reject, { once: true });
  });
}

async function main() {
  const target = await (
    await fetch(`http://127.0.0.1:${CDP_PORT}/json/new?${encodeURIComponent("about:blank")}`, {
      method: "PUT",
    })
  ).json();
  const ws = await connect(target.webSocketDebuggerUrl);

  let lastId = 0;
  const pending = new Map();
  ws.addEventListener("message", (event) => {
    const message = JSON.parse(event.data);
    if (message.id && pending.has(message.id)) {
      const { resolve, reject } = pending.get(message.id);
      pending.delete(message.id);
      if (message.error) reject(new Error(JSON.stringify(message.error)));
      else resolve(message.result);
    }
  });

  function send(method, params = {}) {
    const id = ++lastId;
    ws.send(JSON.stringify({ id, method, params }));
    return new Promise((resolve, reject) => pending.set(id, { resolve, reject }));
  }

  async function evalJs(expression) {
    const response = await send("Runtime.evaluate", {
      expression,
      returnByValue: true,
      awaitPromise: true,
      userGesture: true,
    });
    if (response.exceptionDetails) {
      throw new Error(response.exceptionDetails.exception?.description || "evaluate failed");
    }
    return response.result.value;
  }

  async function waitFor(expression, label, timeout = 25000) {
    const started = Date.now();
    while (Date.now() - started < timeout) {
      const value = await evalJs(expression).catch(() => false);
      if (value) return value;
      await sleep(150);
    }
    const body = await evalJs("document.body.innerText.slice(0, 300)").catch(() => "?");
    throw new Error(`timeout: ${label}; page: ${body}`);
  }

  async function navigate(url) {
    await send("Page.navigate", { url });
    await waitFor("document.readyState === 'complete'", `load ${url}`);
    await waitFor("document.getElementById('root')?.children.length > 0", `render ${url}`);
  }

  await send("Page.enable");
  await send("Runtime.enable");

  const FILL = `
    function fill(selector, value) {
      const input = document.querySelector(selector);
      const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set;
      setter.call(input, value);
      input.dispatchEvent(new Event('input', { bubbles: true }));
    }
  `;

  // A. Expired/broken access token is refreshed automatically on boot.
  await navigate(`${APP}/login`);
  await evalJs(`${FILL}; fill('#login-email', 'reader2@library.local'); fill('#login-password', 'demo12345'); document.querySelector('form').requestSubmit();`);
  await waitFor("!!document.querySelector('.home__title')", "login");

  const refreshBefore = await evalJs("localStorage.getItem('library.refresh')");
  await evalJs("localStorage.setItem('library.access', 'broken.access.token')");
  await send("Page.reload");
  await waitFor("document.readyState === 'complete'", "reload");
  await waitFor("!!document.querySelector('.home__title')", "auto refresh restore");
  const accessAfter = await evalJs("localStorage.getItem('library.access')");
  const pathAfter = await evalJs("location.pathname");
  check("Битый access обновляется через refresh", pathAfter === "/" && accessAfter !== "broken.access.token" && accessAfter.split(".").length === 3);
  check("Refresh-токен при этом не менялся", (await evalJs("localStorage.getItem('library.refresh')")) === refreshBefore);

  // B. Revoked refresh token: entry is impossible, tokens are cleared.
  const refresh = refreshBefore;
  const access = accessAfter;
  const logout = await fetch(`${API}/auth/logout/`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${access}` },
    body: JSON.stringify({ refresh }),
  });
  check("Подготовка: refresh отозван", logout.status === 204, `status=${logout.status}`);

  await evalJs("localStorage.setItem('library.access', 'broken.access.token')");
  await send("Page.reload");
  await waitFor("document.readyState === 'complete'", "reload after revoke");
  await waitFor("location.pathname === '/login'", "redirect after revoke");
  const cleared = await evalJs("JSON.stringify({ access: localStorage.getItem('library.access'), refresh: localStorage.getItem('library.refresh') })");
  check("С отозванным refresh сессия закрывается", cleared === '{"access":null,"refresh":null}', cleared);

  ws.close();
  await fetch(`http://127.0.0.1:${CDP_PORT}/json/close/${target.id}`);
  console.log(`\n${failed === 0 ? "Все проверки пройдены" : `Провалено: ${failed}`}`);
  process.exit(failed ? 1 : 0);
}

main().catch((error) => {
  console.error("ERROR:", error.message);
  process.exit(1);
});

