import { api } from "./client";

/** Размер страницы задан на backend (`PAGE_SIZE = 9`). */
export const PAGE_SIZE = 9;

/** Список книг с поиском, фильтром и пагинацией. */
export async function fetchBooks({ search = "", genre = "", page = 1, signal } = {}) {
  const params = { page };
  if (search) params.search = search;
  if (genre) params.genre = genre;

  const { data } = await api.get("/books/", { params, signal });
  return data;
}

/** Жанры для выпадающего фильтра. */
export async function fetchGenres({ signal } = {}) {
  const { data } = await api.get("/books/genres/", { signal });
  return data.genres;
}

/** Подробная карточка книги. */
export async function fetchBook(bookId, { signal } = {}) {
  const { data } = await api.get(`/books/${bookId}/`, { signal });
  return data;
}

/** Свободные экземпляры книги на выбранный интервал. */
export async function fetchAvailability(bookId, { startDate = "", dueDate = "", signal } = {}) {
  const params = {};
  if (startDate) params.start_date = startDate;
  if (dueDate) params.due_date = dueDate;

  const { data } = await api.get(`/books/${bookId}/availability/`, { params, signal });
  return data;
}

import { useState } from "react";
import { Link, NavLink, useNavigate } from "react-router-dom";

import { getRoleLabel } from "../auth/roles";
import { useAuth } from "../auth/context";
import ErrorMessage from "./ErrorMessage";
import "../styles/header.css";

function getInitials(fullName = "") {
  const parts = fullName.trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return "?";
  return parts
    .slice(0, 2)
    .map((part) => part[0].toUpperCase())
    .join("");
}

function navClass({ isActive }) {
  return `site-header__link${isActive ? " site-header__link--active" : ""}`;
}

/** Шапка авторизованных страниц: навигация и аккаунт. */
export default function SiteHeader() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [loggingOut, setLoggingOut] = useState(false);
  const [error, setError] = useState("");

  async function handleLogout() {
    setError("");
    setLoggingOut(true);
    try {
      await logout();
      navigate("/login", { replace: true });
    } catch {
      setError("Не удалось выйти. Попробуйте ещё раз.");
      setLoggingOut(false);
    }
  }

  if (!user) return null;

  return (
    <div className="site-header">
      <header className="site-header__bar">
        <Link className="site-header__brand" to="/catalog">
          <span className="site-header__brand-mark" aria-hidden="true">
            Б
          </span>
          <span className="site-header__brand-name">Библиотека</span>
        </Link>

        <nav className="site-header__nav" aria-label="Разделы">
          <NavLink className={navClass} to="/catalog">
            Каталог
          </NavLink>
          <NavLink className={navClass} to="/" end>
            Кабинет
          </NavLink>
        </nav>

        <div className="site-header__account">
          <span className="site-header__avatar" aria-hidden="true">
            {getInitials(user.full_name)}
          </span>
          <span className="site-header__account-text">
            <span className="site-header__account-name">{user.full_name}</span>
            <span className="site-header__account-role">{getRoleLabel(user.role)}</span>
          </span>
          <button
            type="button"
            className="button button--ghost site-header__logout"
            onClick={handleLogout}
            disabled={loggingOut}
          >
            {loggingOut ? "Выходим…" : "Выйти"}
          </button>
        </div>
      </header>

      {error && (
        <div className="site-header__alert">
          <ErrorMessage message={error} />
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";

/** Обложка книги с запасным вариантом, если картинка не загрузилась. */
export default function BookCover({ book, large = false }) {
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    setFailed(false);
  }, [book.id, book.cover_url]);

  const className = `book-cover${large ? " book-cover--large" : ""}`;
  const letter = (book.title || "?").trim().charAt(0).toUpperCase() || "?";

  if (!book.cover_url || failed) {
    return (
      <div className={`${className} book-cover--fallback`} aria-hidden="true">
        <span className="book-cover__letter">{letter}</span>
      </div>
    );
  }

  return (
    <div className={className}>
      <img
        className="book-cover__image"
        src={book.cover_url}
        alt={`Обложка книги «${book.title}»`}
        loading="lazy"
        onError={() => setFailed(true)}
      />
    </div>
  );
}

/** Доступность книги: сколько экземпляров свободно. */
export default function AvailabilityBadge({ free, total }) {
  let modifier = "availability--free";
  let label = `Свободно ${free} из ${total}`;

  if (!total) {
    modifier = "availability--none";
    label = "Экземпляров нет";
  } else if (!free) {
    modifier = "availability--busy";
    label = "Нет свободных экземпляров";
  }

  return (
    <span className={`availability ${modifier}`}>
      <span className="availability__dot" aria-hidden="true" />
      {label}
    </span>
  );
}

import { PAGE_SIZE } from "../api/books";

/** Постраничная навигация каталога. */
export default function Pagination({ page, count, onChange }) {
  const totalPages = Math.max(1, Math.ceil(count / PAGE_SIZE));
  if (totalPages <= 1) return null;

  const pages = Array.from({ length: totalPages }, (_, index) => index + 1);

  return (
    <nav className="pagination" aria-label="Страницы каталога">
      <button
        type="button"
        className="button button--ghost pagination__button"
        onClick={() => onChange(page - 1)}
        disabled={page <= 1}
      >
        Назад
      </button>

      <div className="pagination__pages">
        {pages.map((number) => (
          <button
            key={number}
            type="button"
            className={`pagination__page${number === page ? " pagination__page--active" : ""}`}
            onClick={() => onChange(number)}
            disabled={number === page}
            aria-current={number === page ? "page" : undefined}
          >
            {number}
          </button>
        ))}
      </div>

      <button
        type="button"
        className="button button--ghost pagination__button"
        onClick={() => onChange(page + 1)}
        disabled={page >= totalPages}
      >
        Вперёд
      </button>
    </nav>
  );
}

