.page {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 10;
  background-color: rgba(255, 255, 255, 0.96);
  border-bottom: 1px solid var(--line);
  backdrop-filter: blur(8px);
}

.site-header__bar {
  display: flex;
  align-items: center;
  gap: 18px;
  width: 100%;
  max-width: 1180px;
  margin: 0 auto;
  padding: 14px 28px;
}

.site-header__brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--ink);
}

.site-header__brand-mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border-radius: 9px;
  background-color: var(--accent);
  color: #fff;
  font-weight: 700;
}

.site-header__brand-name {
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 0.01em;
}

.site-header__nav {
  display: flex;
  gap: 4px;
}

.site-header__link {
  padding: 8px 12px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 600;
  color: var(--ink-soft);
  transition: background-color 0.15s ease, color 0.15s ease;
}

.site-header__link:hover {
  background-color: var(--surface-muted);
  color: var(--ink);
}

.site-header__link--active {
  background-color: var(--accent-soft);
  color: var(--accent-strong);
}

.site-header__account {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-left: auto;
}

.site-header__avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background-color: var(--accent-soft);
  color: var(--accent-strong);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.03em;
}

.site-header__account-text {
  display: flex;
  flex-direction: column;
  line-height: 1.25;
}

.site-header__account-name {
  font-size: 14px;
  font-weight: 600;
}

.site-header__account-role {
  font-size: 12px;
  color: var(--ink-soft);
}

.site-header__alert {
  width: 100%;
  max-width: 1180px;
  margin: 0 auto;
  padding: 12px 28px 0;
}

@media (max-width: 760px) {
  .site-header__bar {
    flex-wrap: wrap;
    gap: 10px;
    padding: 12px 16px;
  }

  .site-header__nav {
    order: 3;
    width: 100%;
  }

  .site-header__account-text {
    display: none;
  }

  .site-header__logout {
    padding: 8px 12px;
    font-size: 14px;
  }

  .site-header__alert {
    padding: 10px 16px 0;
  }
}

