  align-items: center;
  justify-content: center;
  gap: 14px;
  margin-top: 32px;
}

.pagination__button {
  padding: 9px 14px;
  font-size: 14px;
}

.pagination__pages {
  display: flex;
  gap: 6px;
}

.pagination__page {
