  .catalog__search,
  .catalog__genre {
    flex: 1 1 100%;
  }

  .catalog__grid {
    grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
    gap: 14px;
  }

  .book-card__body {
    padding: 12px 12px 14px;
  }

  .book-card__title {
    font-size: 15px;
  }
}

.book-page {
