.book-meta__label {
  display: block;
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

.book-meta__value {
  display: block;
  margin-top: 4px;
  font-size: 22px;
  font-weight: 700;
}

.book-detail__info > .availability {
  margin-top: 18px;
