input.content:
const CDP_PORT = 9222;
const APP = "http://localhost:5173";
const API = "http://127.0.0.1:8000/api";
const PASSWORD = "demo12345";

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const results = [];

function check(name, ok, extra = "") {
  results.push({ name, ok });
  console.log(`${ok ? "PASS" : "FAIL"}  ${name}${extra ? ` — ${extra}` : ""}`);
  if (!ok) process.exitCode = 1;
}

async function waitForHttp(url, timeout = 30000) {
  const started = Date.now();
  while (Date.now() - started < timeout) {
    try {
      await fetch(url);
      return;
    } catch {
      await sleep(300);
    }
  }
  throw new Error(`service not reachable: ${url}`);
}

async function newTarget() {
  const response = await fetch(
    `http://127.0.0.1:${CDP_PORT}/json/new?${encodeURIComponent("about:blank")}`,
    { method: "PUT" },
  );
  return response.json();
}

function connect(url) {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(url);
    ws.addEventListener("open", () => resolve(ws), { once: true });
    ws.addEventListener("error", reject, { once: true });
  });
}

function toISODate(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function shiftDays(days) {
  const date = new Date();
  date.setDate(date.getDate() + days);
  return toISODate(date);
}

function badgeText(free, total) {
  if (!total) return "Экземпляров нет";
  if (!free) return "Нет свободных экземпляров";
  return `Свободно ${free} из ${total}`;
}

async function main() {
  await waitForHttp(`http://127.0.0.1:${CDP_PORT}/json/version`);
  await waitForHttp(`${APP}/login`);
  await sleep(1000);

  const target = await newTarget();
  const ws = await connect(target.webSocketDebuggerUrl);

  let lastId = 0;
  const pending = new Map();
  ws.addEventListener("message", (event) => {
    const message = JSON.parse(event.data);
    if (message.id && pending.has(message.id)) {
      const { resolve, reject } = pending.get(message.id);
      pending.delete(message.id);
      if (message.error) reject(new Error(JSON.stringify(message.error)));
      else resolve(message.result);
    }
  });

  function send(method, params = {}) {
    const id = ++lastId;
    ws.send(JSON.stringify({ id, method, params }));
    return new Promise((resolve, reject) => pending.set(id, { resolve, reject }));
  }

  async function evalJs(expression) {
    const response = await send("Runtime.evaluate", {
      expression,
      returnByValue: true,
      awaitPromise: true,
      userGesture: true,
    });
    if (response.exceptionDetails) {
      throw new Error(response.exceptionDetails.exception?.description || "evaluate failed");
    }
    return response.result.value;
  }

  async function waitFor(expression, label, timeout = 20000) {
    const started = Date.now();
    while (Date.now() - started < timeout) {
      const value = await evalJs(expression).catch(() => false);
      if (value) return value;
      await sleep(150);
    }
    const body = await evalJs("document.body.innerText.slice(0, 500)").catch(() => "?");
    throw new Error(`timeout: ${label}; page: ${body}`);
  }

  async function navigate(url) {
    await send("Page.navigate", { url });
    await waitFor("document.readyState === 'complete'", `load ${url}`);
    await waitFor("document.getElementById('root')?.children.length > 0", `render ${url}`);
  }

  const token = () => evalJs("localStorage.getItem('library.access')");

  async function apiGet(path, accessToken) {
    const response = await fetch(`${API}${path}`, {
      headers: { Authorization: `Bearer ${accessToken}` },
    });
    if (!response.ok) {
      throw new Error(`api ${path} -> ${response.status}`);
    }
    return response.json();
  }

  const HELPERS = `
    function fill(selector, value) {
      const input = document.querySelector(selector);
      if (!input) throw new Error('no input ' + selector);
      const proto = input instanceof HTMLSelectElement ? HTMLSelectElement.prototype : HTMLInputElement.prototype;
      const setter = Object.getOwnPropertyDescriptor(proto, 'value').set;
      setter.call(input, value);
      input.dispatchEvent(new Event(input instanceof HTMLSelectElement ? 'change' : 'input', { bubbles: true }));
      return input.value;
    }
    function isoDate(offset) {
      const d = new Date();
      d.setDate(d.getDate() + offset);
      const y = d.getFullYear();
      const m = String(d.getMonth() + 1).padStart(2, '0');
      const day = String(d.getDate()).padStart(2, '0');
      return y + '-' + m + '-' + day;
    }
    function cardByTitle(title) {
      return [...document.querySelectorAll('.book-card')].find(
        (card) => card.querySelector('.book-card__title')?.textContent === title,
      );
    }
    function pageButton(number) {
      return [...document.querySelectorAll('.pagination__page')].find(
        (button) => button.textContent === String(number),
      );
    }
    function uiTitles() {
      return JSON.stringify([...document.querySelectorAll('.book-card__title')].map((el) => el.textContent));
    }
    function copyStates() {
      return JSON.stringify([...document.querySelectorAll('.copy-list__item')].map((item) => item.querySelector('.copy-list__state')?.textContent));
    }
  `;

  await send("Page.enable");
  await send("Runtime.enable");

  // 1. Catalog requires login; login lands in catalog.
  await navigate(`${APP}/catalog`);
  await waitFor("location.pathname === '/login'", "redirect to login");
  check("Гость с /catalog попадает на /login", true);

  await evalJs(
    `${HELPERS}; fill('#login-email', 'reader1@library.local'); fill('#login-password', '${PASSWORD}'); document.querySelector('form').requestSubmit();`,
  );
  await waitFor(
    "location.pathname === '/catalog' && document.querySelectorAll('.book-card').length > 0",
    "login to catalog",
    25000,
  );
  check("После входа открывается каталог", location === undefined ? true : true);

  const access = await token();
  if (!access) throw new Error("no access token after login");

  const firstPage = await apiGet("/books/", access);
  const totalCount = firstPage.count;
  const pageSize = firstPage.results.length;

  const brand = await evalJs("document.querySelector('.site-header__brand-name')?.textContent");
  const nav = await evalJs(
    "JSON.stringify([...document.querySelectorAll('.site-header__link')].map((a) => a.textContent))",
  );
  check("Шапка показывает бренд и навигацию", brand === "Библиотека", `${brand} / ${nav}`);

  // 2. First page matches the API.
  const uiFirst = await evalJs(`${HELPERS}; uiTitles()`);
  const apiFirst = JSON.stringify(firstPage.results.map((book) => book.title));
  const summary = await evalJs("document.querySelector('.catalog__summary')?.textContent");
  check("Сводка совпадает с API", summary === `Найдено книг: ${totalCount}`, summary);
  check("Первая страница совпадает с API", uiFirst === apiFirst, uiFirst);

  const cardCount = await evalJs("document.querySelectorAll('.book-card').length");
  check(
    "На первой странице столько же карточек, сколько в API",
    cardCount === pageSize,
    `${cardCount} / ${pageSize}`,
  );

  const busyBook = firstPage.results.find((book) => book.total_copies > 0 && book.free_copies === 0);
  if (busyBook) {
    const busyBadge = await evalJs(
      `${HELPERS}; cardByTitle(${JSON.stringify(busyBook.title)})?.querySelector('.availability')?.textContent`,
    );
    check(
      "Занятая книга помечена в карточке",
      busyBadge === "Нет свободных экземпляров",
      `${busyBadge} (${busyBook.title})`,
    );
  }

  // 3. Target book for detail checks.
  const book = firstPage.results[0];
  const bookUrl = `${APP}/books/${book.id}`;

  // 4. Search by title.
  await evalJs(
    `${HELPERS}; fill('#catalog-search', ${JSON.stringify(book.title)}); document.querySelector('.catalog__filters').requestSubmit();`,
  );
  const titleSearch = await apiGet(
    `/books/?search=${encodeURIComponent(book.title)}`,
    access,
  );
  await waitFor(
    `document.querySelectorAll('.book-card').length === ${titleSearch.results.length} && document.querySelector('.book-card__title')?.textContent === ${JSON.stringify(titleSearch.results[0].title)}`,
    "search by title",
  );
  const searchSummary = await evalJs("document.querySelector('.catalog__summary')?.textContent");
  check(
    "Поиск по названию совпадает с API",
    searchSummary === `Найдено книг: ${titleSearch.count}`,
    searchSummary,
  );

  // 5. Search by author.
  const authorToken = book.author.trim().split(/\s+/).pop();
  await evalJs(
    `${HELPERS}; fill('#catalog-search', ${JSON.stringify(authorToken)}); document.querySelector('.catalog__filters').requestSubmit();`,
  );
  const authorSearch = await apiGet(
    `/books/?search=${encodeURIComponent(authorToken)}`,
    access,
  );
  await waitFor(
    `document.querySelectorAll('.book-card').length === ${authorSearch.results.length} && !document.querySelector('.loader')`,
    "search by author",
  );
  const authorTitles = await evalJs(`${HELPERS}; uiTitles()`);
  check(
    "Поиск по автору совпадает с API",
    authorTitles === JSON.stringify(authorSearch.results.map((item) => item.title)),
    authorTitles,
  );

  // 6. Genre filter.
  const genre = book.genre;
  await navigate(`${APP}/catalog`);
  await waitFor("document.querySelectorAll('.book-card').length > 0", "catalog reload");
  await evalJs(`${HELPERS}; fill('#catalog-genre', ${JSON.stringify(genre)});`);
  const genrePage = await apiGet(`/books/?genre=${encodeURIComponent(genre)}`, access);
  await waitFor(
    `location.search.includes('genre=') && document.querySelectorAll('.book-card').length === ${genrePage.results.length}`,
    "genre filter",
  );
  const genreTitles = await evalJs(`${HELPERS}; uiTitles()`);
  check(
    "Фильтр по жанру совпадает с API",
    genreTitles === JSON.stringify(genrePage.results.map((item) => item.title)),
    genreTitles,
  );

  // 7. Pagination.
  await navigate(`${APP}/catalog`);
  await waitFor(
    `document.querySelectorAll('.book-card').length === ${pageSize}`,
    "catalog page 1",
  );
  const page2 = await apiGet("/books/?page=2", access);
  await evalJs(`${HELPERS}; pageButton(2)?.click();`);
  await waitFor(
    `location.search.includes('page=2') && document.querySelectorAll('.book-card').length === ${page2.results.length}`,
    "page 2",
  );
  const uiPage2 = await evalJs(`${HELPERS}; uiTitles()`);
  check(
    "Вторая страница совпадает с API",
    uiPage2 === JSON.stringify(page2.results.map((item) => item.title)),
    uiPage2,
  );

  const totalPages = Math.max(1, Math.ceil(totalCount / pageSize));
  const lastPage = await apiGet(`/books/?page=${totalPages}`, access);
  await evalJs(`${HELPERS}; pageButton(${totalPages})?.click();`);
  await waitFor(
    `location.search.includes('page=${totalPages}') && document.querySelectorAll('.book-card').length === ${lastPage.results.length}`,
    "last page",
  );
  const uiLast = await evalJs(`${HELPERS}; uiTitles()`);
  check(
    `Последняя страница (${totalPages}) совпадает с API`,
    uiLast === JSON.stringify(lastPage.results.map((item) => item.title)),
    uiLast,
  );

  // 8. Book card opens detail.
  await evalJs(`${HELPERS}; fill('#catalog-search', ${JSON.stringify(book.title)}); document.querySelector('.catalog__filters').requestSubmit();`);
  await waitFor(
    `document.querySelectorAll('.book-card').length === 1 && !!document.querySelector('a[href="/books/${book.id}"]')`,
    "book card",
  );
  await evalJs(`document.querySelector('a[href="/books/${book.id}"]')?.click();`);
  await waitFor(
    `location.pathname === '/books/${book.id}' && !!document.querySelector('.book-detail__title')`,
    "book detail",
  );
  const detailTitle = await evalJs("document.querySelector('.book-detail__title')?.textContent");
  const detailAuthor = await evalJs("document.querySelector('.book-detail__author')?.textContent");
  check("Карточка книги открывается", detailTitle === book.title, detailTitle);
  check("Карточка показывает автора", detailAuthor === book.author, detailAuthor);

  const expectedBadge = badgeText(book.free_copies, book.total_copies);
  await waitFor(
    `!document.querySelector('.book-availability .loader') && document.querySelector('.book-availability .availability')?.textContent === ${JSON.stringify(expectedBadge)}`,
    "default availability",
  );
  const copyCount = await evalJs("document.querySelectorAll('.copy-list__item').length");
  check(
    "Доступность по умолчанию совпадает с API",
    expectedBadge === badgeText(book.free_copies, book.total_copies),
    `${expectedBadge}; экземпляров: ${copyCount}`,
  );

  // 9. Availability for a future period compared with the API.
  const start = shiftDays(200);
  const due = shiftDays(214);
  const future = await apiGet(
    `/books/${book.id}/availability/?start_date=${start}&due_date=${due}`,
    access,
  );
  await evalJs(
    `${HELPERS}; fill('#availability-start', '${start}'); fill('#availability-due', '${due}'); document.querySelector('.book-availability__form').requestSubmit();`,
  );
  const futureBadge = badgeText(future.free_copies, future.total_copies);
  await waitFor(
    `!document.querySelector('.book-availability .loader') && document.querySelector('.book-availability .availability')?.textContent === ${JSON.stringify(futureBadge)}`,
    "future availability",
  );
  const uiStates = await evalJs(`${HELPERS}; copyStates()`);
  const apiStates = JSON.stringify(
    future.copies.map((copy) => (copy.is_available ? "Свободен" : "Занят")),
  );
  check(
    "На будущие даты состояние экземпляров совпадает с API",
    uiStates === apiStates,
    `${uiStates} / ${futureBadge}`,
  );

  const shownPeriod = await evalJs(
    "document.querySelector('.book-availability__period')?.textContent",
  );
  const format = (iso) => iso.split("-").reverse().join(".");
  check(
    "Период показан в результатах",
    shownPeriod?.includes(format(start)) && shownPeriod?.includes(format(due)),
    shownPeriod,
  );

  // 10. Client-side date validation.
  await evalJs(
    `${HELPERS}; fill('#availability-start', isoDate(2)); fill('#availability-due', isoDate(1)); document.querySelector('.book-availability__form').requestSubmit();`,
  );
  const dateError = await waitFor(
    "document.querySelector('.book-availability > .field__error')?.textContent",
    "date validation",
  );
  check(
    "Неверные даты подсвечиваются без запроса",
    dateError === "Дата возврата должна быть позже даты начала",
    dateError,
  );

  // 11. Empty search state.
  await evalJs("document.querySelector('.book-page__back')?.click();");
  await waitFor("location.pathname === '/catalog'", "back to catalog");
  await waitFor("document.querySelectorAll('.book-card').length === 1", "previous search kept");
  await evalJs(
    `${HELPERS}; fill('#catalog-search', 'несуществующая книга'); document.querySelector('.catalog__filters').requestSubmit();`,
  );
  const emptyTitle = await waitFor(
    "document.querySelector('.catalog__empty-title')?.textContent",
    "empty search",
  );
  check(
    "Пустой результат поиска показывает заглушку",
    emptyTitle === "Ничего не найдено",
    emptyTitle,
  );
  await evalJs("document.querySelector('.catalog__empty button')?.click();");
  await waitFor(
    `document.querySelectorAll('.book-card').length === ${pageSize} && !location.search`,
    "reset empty search",
  );
  check("Сброс фильтров возвращает каталог", true);

  // 12. Query is preserved after a full reload, session too.
  await navigate(`${APP}/catalog?search=${encodeURIComponent(book.title)}`);
  await waitFor(
    `document.querySelectorAll('.book-card').length === 1 && document.querySelector('#catalog-search')?.value === ${JSON.stringify(book.title)}`,
    "reload with query",
  );
  check("Поиск сохраняется в адресе и после перезагрузки", true);

  // 13. Logout from shared header.
  await evalJs("document.querySelector('.site-header__logout')?.click();");
  await waitFor("location.pathname === '/login'", "logout");
  const stored = await evalJs(
    "JSON.stringify({ access: localStorage.getItem('library.access'), refresh: localStorage.getItem('library.refresh') })",
  );
  check(
    "Выход из общей шапки очищает сессию",
    stored === '{"access":null,"refresh":null}',
    stored,
  );

  ws.close();
  await fetch(`http://127.0.0.1:${CDP_PORT}/json/close/${target.id}`);

  const failed = results.filter((item) => !item.ok).length;
  console.log(`\n${results.length - failed}/${results.length} проверок пройдено`);
  process.exit(failed ? 1 : 0);
}

main().catch((error) => {
  console.error("ERROR:", error.message);
  process.exit(1);
});

