import { api } from "./client";

/** Создать бронь на экземпляр или на свободный экземпляр книги. */
export async function createLoan({
  copyId = null,
  bookId = null,
  startDate = "",
  dueDate = "",
  comment = "",
} = {}) {
  const payload = {};
  if (copyId) payload.copy_id = copyId;
  if (bookId) payload.book_id = bookId;
  if (startDate) payload.start_date = startDate;
  if (dueDate) payload.due_date = dueDate;
  if (comment) payload.comment = comment;

  const { data } = await api.post("/loans/", payload);
  return data;
}

/** Список броней с фильтрами и серверной пагинацией. */
export async function fetchLoans({
  status = "",
  bookId = null,
  readerId = null,
  activeOn = "",
  page = 1,
  signal,
} = {}) {
  const params = { page };
  if (status) params.status = status;
  if (bookId) params.book_id = bookId;
  if (readerId) params.reader_id = readerId;
  if (activeOn) params.active_on = activeOn;

  const { data } = await api.get("/loans/", { params, signal });
  return data;
}

/** Сменить статус брони: выдать, вернуть или отменить. */
export async function updateLoanStatus(loanId, status) {
  const { data } = await api.patch(`/loans/${loanId}/status/`, { status });
  return data;
}

import { api } from "./client";

/** Встать в очередь на книгу. */
export async function createReservation(bookId) {
  const { data } = await api.post("/reservations/", { book_id: bookId });
  return data;
}

/** Мои заявки и позиция в очереди. */
export async function fetchMyReservations({ status = "", page = 1, signal } = {}) {
  const params = { page };
  if (status) params.status = status;

  const { data } = await api.get("/reservations/my/", { params, signal });
  return data;
}

/** Все заявки для библиотекаря: фильтр по книге и статусу. */
export async function fetchReservations({
  bookId = null,
  status = "",
  page = 1,
  signal,
} = {}) {
  const params = { page };
  if (bookId) params.book_id = bookId;
  if (status) params.status = status;

  const { data } = await api.get("/reservations/", { params, signal });
  return data;
}

/** Отменить свою заявку. */
export async function cancelReservation(reservationId) {
  await api.delete(`/reservations/${reservationId}/`);
}

/** Общие функции дат для интерфейса. */

export function toISODate(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

export function todayISO() {
  return toISODate(new Date());
}

export function addDays(isoDate, days) {
  const date = new Date(`${isoDate}T00:00:00`);
  date.setDate(date.getDate() + days);
  return toISODate(date);
}

export function formatDate(isoDate) {
  if (!isoDate) return "";
  const [year, month, day] = isoDate.split("-");
  return `${day}.${month}.${year}`;
}

export function formatDateTime(value) {
  if (!value) return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleString("ru-RU", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

const LOAN_LABELS = {
  created: "Забронирована",
  active: "Выдана",
  returned: "Возвращена",
  cancelled: "Отменена",
};

const RESERVATION_LABELS = {
  waiting: "Ожидает",
  ready: "Готова к выдаче",
  fulfilled: "Выполнена",
  cancelled: "Отменена",
  expired: "Просрочена",
};

/** Статус брони или заявки в очереди. */
export default function StatusBadge({ status, kind = "loan" }) {
  const labels = kind === "reservation" ? RESERVATION_LABELS : LOAN_LABELS;
  return (
    <span className={`status status--${status}`}>
      {labels[status] || status}
    </span>
  );
}

import { useState } from "react";
import { Link } from "react-router-dom";

import { getErrorMessage } from "../api/client";
import { createLoan } from "../api/loans";
import { cancelReservation, createReservation } from "../api/reservations";
import { useAuth } from "../auth/context";
import { formatDateTime } from "../utils/dates";
import ErrorMessage from "./ErrorMessage";

/** Действия читателя на странице книги: бронь, очередь, удержание. */
export default function BookingPanel({ book, availability, period, onChanged }) {
  const { user } = useAuth();
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");

  if (!availability) return null;

  if (user.role !== "reader") {
    return (
      <p className="booking-panel__note">
        Оформление брони доступно читателям. Сотрудник работает с выдачами в
        разделе «Выдача».
      </p>
    );
  }

  const reservation = availability.my_reservation;
  const freeCopies = availability.available_copies || [];

  async function run(action, successText) {
    setBusy(true);
    setError("");
    setMessage("");
    try {
      await action();
      setMessage(successText);
      onChanged();
    } catch (requestError) {
      setError(
        getErrorMessage(requestError, "Не удалось выполнить действие. Попробуйте ещё раз."),
      );
    } finally {
      setBusy(false);
    }
  }

  function borrow(copyId) {
    return run(
      () =>
        createLoan({
          copyId,
          startDate: period.startDate,
          dueDate: period.dueDate,
        }),
      "Бронь создана. Библиотекарь выдаст книгу, когда вы придёте.",
    );
  }

  function joinQueue() {
    return run(
      () => createReservation(book.id),
      "Вы встали в очередь. Мы покажем вашу позицию в разделе «Моя очередь».",
    );
  }

  function cancelHold() {
    if (!reservation) return undefined;
    if (!window.confirm("Отменить заявку в очереди?")) return undefined;
    return run(
      () => cancelReservation(reservation.id),
      "Заявка отменена. Экземпляр перейдёт следующему читателю.",
    );
  }

  let action = null;

  if (!availability.total_copies) {
    action = (
      <p className="booking-panel__note">
        У книги нет активных экземпляров, поэтому очередь недоступна.
      </p>
    );
  } else if (reservation?.status === "ready") {
    action = (
      <>
        <p className="booking-panel__message booking-panel__message--hold">
          За вами удержан экземпляр
          {reservation.hold_until
            ? ` до ${formatDateTime(reservation.hold_until)}`
            : ""}
          . Оформите бронь, чтобы забрать книгу.
        </p>
        <div className="booking-panel__actions">
          <button
            type="button"
            className="button button--primary"
            disabled={busy}
            onClick={() => borrow(reservation.hold_copy_id || freeCopies[0]?.id)}
          >
            {busy ? "Оформляем…" : "Оформить бронь"}
          </button>
          <button
            type="button"
            className="button button--ghost"
            disabled={busy}
            onClick={cancelHold}
          >
            Отменить заявку
          </button>
        </div>
      </>
    );
  } else if (reservation?.status === "waiting") {
    action = (
      <>
        <p className="booking-panel__message booking-panel__message--hold">
          Вы в очереди. Позиция: {reservation.position ?? "—"}. Заявка
          автоматически станет готова, когда экземпляр освободится.
        </p>
        <div className="booking-panel__actions">
          <Link className="button button--ghost" to="/my/queue">
            Моя очередь
          </Link>
          <button
            type="button"
            className="button button--ghost"
            disabled={busy}
            onClick={cancelHold}
          >
            Отменить заявку
          </button>
        </div>
      </>
    );
  } else if (freeCopies.length > 0) {
    action = (
      <div className="booking-panel__actions">
        <button
          type="button"
          className="button button--primary"
          disabled={busy}
          onClick={() => borrow(freeCopies[0].id)}
        >
          {busy ? "Бронируем…" : "Забронировать"}
        </button>
        <span className="booking-panel__hint">
          Свободно экземпляров: {availability.free_copies}
        </span>
      </div>
    );
  } else {
    action = (
      <>
        <p className="booking-panel__message">
          На выбранные даты свободных экземпляров нет. В очереди ожидают:{" "}
          {availability.waiting_count}.
        </p>
        <div className="booking-panel__actions">
          <button
            type="button"
            className="button button--primary"
            disabled={busy}
            onClick={joinQueue}
          >
            {busy ? "Встаём в очередь…" : "Встать в очередь"}
          </button>
          <Link className="button button--ghost" to="/my/queue">
            Моя очередь
          </Link>
        </div>
      </>
    );
  }

  return (
    <section className="booking-panel" aria-label="Бронирование">
      {action}
      {error && <ErrorMessage message={error} />}
      {message && (
        <p className="booking-panel__success" role="status">
          {message}
        </p>
      )}
    </section>
  );
}

"""Эндпоинты броней: создание, списки, смена статуса."""

from rest_framework import generics, status
from rest_framework.exceptions import ValidationError
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework.views import APIView

from loans.models import Loan
from loans.serializers import (
    LoanCreateSerializer,
    LoanQuerySerializer,
    LoanSerializer,
    LoanStatusSerializer,
)
from loans.services import LoanError, change_loan_status, create_loan
from loans.statuses import LoanStatus
from users.api import ApiErrorMixin
from users.models import User
from users.permissions import IsReader


def scoped_loans(user):
    """Читатель видит только свои брони, сотрудники — все."""
    queryset = Loan.objects.select_related("reader", "copy__book")
    if user.role == User.Role.READER:
        return queryset.filter(reader=user)
    return queryset


def parse_filters(request):
    """Проверить параметры списка; статус допускает несколько через запятую."""
    allowed = ("status", "book_id", "reader_id", "active_on")
    clean = {
        key: value
        for key, value in request.query_params.items()
        if key in allowed and value not in ("", None)
    }
    serializer = LoanQuerySerializer(data=clean)
    serializer.is_valid(raise_exception=True)

    data = serializer.validated_data
    statuses = []
    raw_statuses = data.get("status")
    if raw_statuses:
        statuses = [item.strip() for item in raw_statuses.split(",") if item.strip()]
        invalid = [item for item in statuses if item not in LoanStatus.values]
        if invalid:
            raise ValidationError(
                {"status": f"Неизвестный статус: {', '.join(invalid)}"}
            )

    return {
        "statuses": statuses,
        "book_id": data.get("book_id"),
        "reader_id": data.get("reader_id"),
        "active_on": data.get("active_on"),
    }


def apply_filters(queryset, filters):
    if filters["statuses"]:
        queryset = queryset.filter(status__in=filters["statuses"])
    if filters["book_id"]:
        queryset = queryset.filter(copy__book_id=filters["book_id"])
    if filters["reader_id"]:
        queryset = queryset.filter(reader_id=filters["reader_id"])
    if filters["active_on"]:
        date = filters["active_on"]
        queryset = queryset.filter(start_date__lte=date, due_date__gt=date)
    return queryset


class LoanCollectionView(ApiErrorMixin, generics.ListAPIView):
    """`GET` — список броней, `POST` — создание брони читателем."""

    serializer_class = LoanSerializer

    def get_permissions(self):
        if self.request.method == "POST":
            return [IsReader()]
        return [IsAuthenticated()]

    def get_queryset(self):
        queryset = scoped_loans(self.request.user)
        queryset = apply_filters(queryset, parse_filters(self.request))
        return queryset.order_by("-created_at", "-id")

    def post(self, request):
        serializer = LoanCreateSerializer(data=request.data)
        if not serializer.is_valid():
            return Response(
                {
                    "detail": "Проверьте параметры запроса",
                    "code": "validation_error",
                    "fields": serializer.errors,
                },
                status=status.HTTP_400_BAD_REQUEST,
            )

        data = serializer.validated_data
        if not data.get("copy_id") and not data.get("book_id"):
            return Response(
                {"detail": "Укажите экземпляр или книгу", "code": "target_required"},
                status=status.HTTP_400_BAD_REQUEST,
            )
        try:
            loan = create_loan(
                reader=request.user,
                copy_id=data.get("copy_id"),
                book_id=data.get("book_id"),
                start_date=data.get("start_date"),
                due_date=data.get("due_date"),
                comment=data.get("comment", ""),
                request=request,
            )
        except LoanError as error:
            return Response(
                {"detail": error.detail, "code": error.code},
                status=error.status_code,
            )

        return Response(LoanSerializer(loan).data, status=status.HTTP_201_CREATED)


class LoanDetailView(ApiErrorMixin, generics.RetrieveAPIView):
    """Одна бронь: своя для читателя, любая для сотрудника."""

    permission_classes = [IsAuthenticated]
    serializer_class = LoanSerializer

    def get_queryset(self):
        return scoped_loans(self.request.user)


class LoanStatusView(ApiErrorMixin, APIView):
    """Смена статуса по матрице переходов из `loans/statuses.py`."""

    permission_classes = [IsAuthenticated]

    def patch(self, request, pk):
        serializer = LoanStatusSerializer(data=request.data)
        if not serializer.is_valid():
            return Response(
                {
                    "detail": "Проверьте параметры запроса",
                    "code": "validation_error",
                    "fields": serializer.errors,
                },
                status=status.HTTP_400_BAD_REQUEST,
            )

        try:
            loan = change_loan_status(
                loan_id=pk,
                new_status=serializer.validated_data["status"],
                actor=request.user,
                request=request,
            )
        except LoanError as error:
            return Response(
                {"detail": error.detail, "code": error.code},
                status=error.status_code,
            )

        return Response(LoanSerializer(loan).data)

