.dashboard {
  flex: 1;
  width: 100%;
  max-width: 1080px;
  margin: 0 auto;
  padding: 34px 28px 72px;
}

.dashboard__head {
  max-width: 720px;
}

.dashboard__eyebrow {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--accent);
}

.dashboard__title {
  margin-top: 8px;
  font-size: 32px;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.dashboard__lead {
  margin-top: 8px;
  color: var(--ink-soft);
}

.dashboard__tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 24px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--line);
}

.dashboard__tab {
  padding: 8px 14px;
  font-family: inherit;
  font-size: 14px;
  font-weight: 600;
  color: var(--ink-soft);
  background-color: transparent;
  border: 1px solid transparent;
