import { Navigate, Outlet, useLocation } from "react-router-dom";

import Loader from "../components/Loader";
import { useAuth } from "./context";

/** Пускает только авторизованных; запоминает адрес, куда пользователь шёл. */
export function ProtectedRoute() {
  const { user, initializing } = useAuth();
  const location = useLocation();

  if (initializing) {
    return <Loader full height="page" text="Проверяем авторизацию…" />;
  }

  if (!user) {
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  return <Outlet />;
}

/** Пускает только пользователей с нужной ролью, остальных возвращает в каталог. */
export function RoleRoute({ roles }) {
  const { user, initializing } = useAuth();
  const location = useLocation();

  if (initializing) {
    return <Loader full height="page" text="Проверяем авторизацию…" />;
  }

  if (!user) {
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  if (!roles.includes(user.role)) {
    return <Navigate to="/catalog" replace />;
  }

  return <Outlet />;
}

/** Страницы входа и регистрации: авторизованному здесь делать нечего. */
export function PublicOnlyRoute() {
  const { user, initializing } = useAuth();

  if (initializing) {
    return <Loader full height="page" text="Проверяем авторизацию…" />;
  }

  if (user) {
    return <Navigate to="/catalog" replace />;
  }

  return <Outlet />;
}

import { Navigate, Route, Routes } from "react-router-dom";

import { ProtectedRoute, PublicOnlyRoute, RoleRoute } from "./auth/ProtectedRoute";
import BookDetailPage from "./pages/BookDetailPage";
import CatalogPage from "./pages/CatalogPage";
import HomePage from "./pages/HomePage";
import LibrarianPage from "./pages/LibrarianPage";
import LoginPage from "./pages/LoginPage";
import MyLoansPage from "./pages/MyLoansPage";
import MyQueuePage from "./pages/MyQueuePage";
import RegisterPage from "./pages/RegisterPage";

const READER_ROLES = ["reader"];
const STAFF_ROLES = ["librarian", "admin"];

export default function App() {
  return (
    <Routes>
      <Route element={<PublicOnlyRoute />}>
        <Route path="/login" element={<LoginPage />} />
        <Route path="/register" element={<RegisterPage />} />
      </Route>

      <Route element={<ProtectedRoute />}>
        <Route path="/" element={<HomePage />} />
        <Route path="/catalog" element={<CatalogPage />} />
        <Route path="/books/:id" element={<BookDetailPage />} />
      </Route>

      <Route element={<RoleRoute roles={READER_ROLES} />}>
        <Route path="/my" element={<MyLoansPage />} />
        <Route path="/my/queue" element={<MyQueuePage />} />
      </Route>

      <Route element={<RoleRoute roles={STAFF_ROLES} />}>
        <Route path="/librarian" element={<LibrarianPage />} />
      </Route>

      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
}

