const CDP_PORT = 9222;
const APP = "http://localhost:5173";
const API = "http://127.0.0.1:8000/api";
const PASSWORD = "demo12345";

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function api(method, path, token, body) {
  const headers = {};
  if (body) headers["Content-Type"] = "application/json";
  if (token) headers.Authorization = `Bearer ${token}`;
  const res = await fetch(`${API}${path}`, {
    method,
    headers,
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  return { status: res.status, data: text ? JSON.parse(text) : {} };
}

async function loginApi(email) {
  const { data } = await api("POST", "/auth/login/", null, { email, password: PASSWORD });
  return data.access;
}

function iso(offset) {
  const d = new Date();
  d.setDate(d.getDate() + offset);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

const results = [];
function check(label, ok, details) {
  results.push({ label, ok });
  console.log(`${ok ? "PASS" : "FAIL"}  ${label}${details ? ` — ${details}` : ""}`);
}

async function main() {
  const admin = await loginApi("admin@library.local");
  const librarian = await loginApi("librarian1@library.local");
  const reader = await loginApi("reader2@library.local");

  const stamp = Date.now().toString().slice(-6);
  const title = `E2E снятие ${stamp}`;
  const book = await api("POST", "/books/", admin, {
    title, author: "E2E", genre: "E2E", year: 2026,
  });
  const bookId = book.data.id;
  const copy = await api("POST", `/books/${bookId}/copies/`, admin, {
    inventory_number: `E2E-C-${stamp}`, condition: "good",
  });
  const loan = await api("POST", "/loans/", reader, {
    copy_id: copy.data.id, start_date: iso(0), due_date: iso(3),
  });
  check("Подготовлена бронь", loan.status === 201, JSON.stringify(loan.data));

  const target = await (await fetch(
    `http://127.0.0.1:${CDP_PORT}/json/new?${encodeURIComponent("about:blank")}`,
    { method: "PUT" },
  )).json();
  const ws = await new Promise((resolve, reject) => {
    const s = new WebSocket(target.webSocketDebuggerUrl);
    s.addEventListener("open", () => resolve(s), { once: true });
    s.addEventListener("error", reject, { once: true });
  });

  let lastId = 0;
  const pending = new Map();
  ws.addEventListener("message", (e) => {
    const m = JSON.parse(e.data);
    if (m.id && pending.has(m.id)) {
      const p = pending.get(m.id);
      pending.delete(m.id);
      m.error ? p.reject(new Error(JSON.stringify(m.error))) : p.resolve(m.result);
    }
  });
  const send = (method, params = {}) => {
    const id = ++lastId;
    ws.send(JSON.stringify({ id, method, params }));
    return new Promise((resolve, reject) => pending.set(id, { resolve, reject }));
  };
  const evalJs = async (expression) => {
    const r = await send("Runtime.evaluate", {
      expression, returnByValue: true, awaitPromise: true, userGesture: true,
    });
    if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || "eval failed");
    return r.result.value;
  };
  const waitFor = async (expr, label, timeout = 20000) => {
    const start = Date.now();
    while (Date.now() - start < timeout) {
      const v = await evalJs(expr).catch(() => false);
      if (v) return v;
      await sleep(120);
    }
    throw new Error(`timeout: ${label}`);
  };
  const navigate = async (url) => {
    await send("Page.navigate", { url });
    await waitFor("document.readyState === 'complete'", `load ${url}`);
    await waitFor("document.getElementById('root')?.children.length > 0", `render ${url}`);
  };

  await send("Page.enable");
  await send("Runtime.enable");
  await send("Storage.clearDataForOrigin", { origin: APP, storageTypes: "local_storage" });

  await navigate(`${APP}/login`);
  await evalJs(
    `(() => { const set = (sel, v) => { const i = document.querySelector(sel); Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set.call(i, v); i.dispatchEvent(new Event('input', { bubbles: true })); }; set('#login-email', 'librarian1@library.local'); set('#login-password', '${PASSWORD}'); document.querySelector('form').requestSubmit(); })()`,
  );
  await waitFor("location.pathname === '/catalog'", "login", 25000);

  await navigate(`${APP}/librarian`);
  await waitFor(
    `[...document.querySelectorAll('.record-card__title')].some((el) => el.textContent === ${JSON.stringify(title)})`,
    "loan card",
  );
  const hasCancel = await evalJs(
    `(() => { const card = [...document.querySelectorAll('.record-card')].find((el) => el.querySelector('.record-card__title')?.textContent === ${JSON.stringify(title)}); return !![...card.querySelectorAll('.button')].find((b) => b.textContent === 'Снять бронь'); })()`,
  );
  check("У брони есть кнопка «Снять бронь»", hasCancel === true, String(hasCancel));

  await evalJs("window.confirm = () => true;");
  await evalJs(
    `(() => { const card = [...document.querySelectorAll('.record-card')].find((el) => el.querySelector('.record-card__title')?.textContent === ${JSON.stringify(title)}); [...card.querySelectorAll('.button')].find((b) => b.textContent === 'Снять бронь')?.click(); })()`,
  );
  await waitFor(
    `document.querySelector('.dashboard__success')?.textContent?.includes('снята')`,
    "cancel success",
  );
  const message = await evalJs("document.querySelector('.dashboard__success')?.textContent");
  check("Библиотекарь снял бронь", message?.includes(title) && message?.includes("снята"), message);

  const after = await api("GET", `/loans/${loan.data.id}/`, librarian);
  check("Статус брони в API — cancelled", after.data.status === "cancelled", after.data.status);
  const gone = await evalJs(
    `![...document.querySelectorAll('.record-card__title')].some((el) => el.textContent === ${JSON.stringify(title)})`,
  );
  check("Снятая бронь ушла из списка выдач", gone === true, String(gone));

  ws.close();
  await fetch(`http://127.0.0.1:${CDP_PORT}/json/close/${target.id}`);

  await api("DELETE", `/loans/${loan.data.id}/`, admin);
  await api("DELETE", `/books/${bookId}/`, admin);

  const failed = results.filter((item) => !item.ok).length;
  console.log(`\n${results.length - failed}/${results.length} проверок пройдено; book=${bookId} loan=${loan.data.id}`);
  process.exit(failed ? 1 : 0);
}

main().catch((error) => {
  console.error("ERROR:", error.message);
  process.exit(1);
});

