  border-radius: var(--radius);
  box-shadow: 0 8px 20px rgba(31, 36, 48, 0.04);
}

.admin-panel__head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line);
}

.admin-panel__title {
  font-size: 19px;
  font-weight: 700;
}

.admin-panel__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.admin-form__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 14px 18px;
  margin-top: 14px;
}

.admin-form__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 16px;
}

.admin-textarea {
