}

.admin-check input {
  width: 16px;
  height: 16px;
  accent-color: var(--accent);
}

.admin-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 14px;
}

.admin-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 14px 20px;
  padding: 16px 18px;
  background-color: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
}

.admin-row__main {
  display: flex;
  flex-direction: column;
  min-width: 220px;
  flex: 1 1 260px;
}

.admin-row__title {
  font-size: 16px;
  font-weight: 700;
}

.admin-row__meta {
  font-size: 13px;
  color: var(--ink-soft);
}

.admin-row__side {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 14px;
}

.admin-row__role {
  display: flex;
  align-items: center;
  gap: 8px;
}

.admin-row__role-label {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

.admin-row__select {
  width: auto;
  min-width: 150px;
  padding: 7px 10px;
  font-size: 13.5px;
}

.admin-row__hint {
  font-size: 12.5px;
  font-style: italic;
  color: var(--ink-soft);
}

.admin-row__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.admin-row__button {
  padding: 7px 12px;
  font-size: 13px;
}

.admin-row__button--danger {
  color: var(--danger);
}

.admin-row__button--danger:hover:not(:disabled) {
  color: var(--danger);
  background-color: var(--danger-soft);
}

.admin-copies {
  border-color: var(--accent-soft);
}

.admin-copy-form {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 14px;
  margin-top: 16px;
  padding: 14px 16px;
  background-color: var(--surface-muted);
  border-radius: var(--radius-sm);
}

.admin-copy-form .field {
  flex: 0 1 220px;
}

.admin-copy-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 14px;
}

.admin-copy-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px 16px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
}

.admin-copy-row__number {
  font-weight: 600;
}

.admin-copy-row__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.admin-empty-text {
  margin-top: 16px;
  color: var(--ink-soft);
}

@media (max-width: 720px) {
  .admin-toolbar,
  .admin-row,
  .admin-row__side {
    align-items: stretch;
    flex-direction: column;
  }

  .admin-filters .field,
  .admin-copy-form .field {
    flex: 1 1 100%;
  }
}

