async function api(method, path, token, body) {
  const headers = {};
  if (body) headers["Content-Type"] = "application/json";
  if (token) headers.Authorization = `Bearer ${token}`;
  const res = await fetch(`${API}${path}`, {
    method,
    headers,
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  return { status: res.status, data: text ? JSON.parse(text) : {} };
}

async function loginApi(email, password = PASSWORD) {
  return api("POST", "/auth/login/", null, { email, password });
}

const results = [];
function check(label, ok, details) {
  results.push({ label, ok });
  console.log(`${ok ? "PASS" : "FAIL"}  ${label}${details ? ` — ${details}` : ""}`);
}

async function main() {
  const adminLogin = await loginApi("admin@library.local");
  const librarianLogin = await loginApi("librarian1@library.local");
  const readerLogin = await loginApi("reader2@library.local");
  const admin = adminLogin.data.access;
  const librarian = librarianLogin.data.access;
  const reader = readerLogin.data.access;
  check(
    "Логины демо-пользователей",
    Boolean(admin && librarian && reader),
    JSON.stringify([adminLogin.status, librarianLogin.status, readerLogin.status]),
  );

  const stamp = Date.now().toString().slice(-6);
  const newEmail = `e2e-admin-${stamp}@test.local`;
  const bookTitle = `E2E Админ книга ${stamp}`;
  const inventory = `E2E-ADM-${stamp}`;

  const readerUsers = await api("GET", "/admin/users/", reader);
  const librarianUsers = await api("GET", "/admin/users/", librarian);
  const adminUsers = await api("GET", "/admin/users/", admin);
  check("Reader получает 403 на /api/admin/users/", readerUsers.status === 403, String(readerUsers.status));
  check("Librarian получает 403 на /api/admin/users/", librarianUsers.status === 403, String(librarianUsers.status));
  check("Admin получает список пользователей", adminUsers.status === 200 && adminUsers.data.count >= 3, String(adminUsers.data.count));

  const readerLoans = await api("GET", "/loans/", reader);
  const adminLoans = await api("GET", "/loans/", admin);
  const adminQueue = await api("GET", "/reservations/", admin);
  check(
    "Admin видит все брони и очередь",
    adminLoans.status === 200 && adminQueue.status === 200 && readerLoans.status === 200,
    JSON.stringify([adminLoans.data.count, adminQueue.data.count]),
  );

  const target = await (await fetch(
    `http://127.0.0.1:${CDP_PORT}/json/new?${encodeURIComponent("about:blank")}`,
    { method: "PUT" },
  )).json();
  const ws = await new Promise((resolve, reject) => {
    const s = new WebSocket(target.webSocketDebuggerUrl);
    s.addEventListener("open", () => resolve(s), { once: true });
    s.addEventListener("error", reject, { once: true });
  });

  let lastId = 0;
  const pending = new Map();
  ws.addEventListener("message", (e) => {
    const m = JSON.parse(e.data);
    if (m.id && pending.has(m.id)) {
      const p = pending.get(m.id);
      pending.delete(m.id);
      m.error ? p.reject(new Error(JSON.stringify(m.error))) : p.resolve(m.result);
    }
  });
  const send = (method, params = {}) => {
    const id = ++lastId;
    ws.send(JSON.stringify({ id, method, params }));
    return new Promise((resolve, reject) => pending.set(id, { resolve, reject }));
  };
  const evalJs = async (expression) => {
    const r = await send("Runtime.evaluate", {
      expression, returnByValue: true, awaitPromise: true, userGesture: true,
    });
    if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || "eval failed");
    return r.result.value;
  };
  const waitFor = async (expr, label, timeout = 25000) => {
    const start = Date.now();
    while (Date.now() - start < timeout) {
      const v = await evalJs(expr).catch(() => false);
      if (v) return v;
      await sleep(120);
    }
    throw new Error(`timeout: ${label}`);
  };
  const navigate = async (url) => {
    await send("Page.navigate", { url });
    await waitFor("document.readyState === 'complete'", `load ${url}`);
    await waitFor("document.getElementById('root')?.children.length > 0", `render ${url}`);
  };
  const loginBrowser = async (email) => {
    await send("Storage.clearDataForOrigin", { origin: APP, storageTypes: "local_storage" });
    await navigate(`${APP}/login`);
    await evalJs(
      `(() => { const set = (sel, v) => { const i = document.querySelector(sel); Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set.call(i, v); i.dispatchEvent(new Event('input', { bubbles: true })); }; set('#login-email', ${JSON.stringify(email)}); set('#login-password', '${PASSWORD}'); document.querySelector('form').requestSubmit(); })()`,
    );
    await waitFor("location.pathname === '/catalog'", `login ${email}`);
  };
  const clickText = (selector, text) =>
    evalJs(
      `(() => { const el = [...document.querySelectorAll(${JSON.stringify(selector)})].find((b) => b.textContent.trim() === ${JSON.stringify(text)}); if (!el) return false; el.click(); return true; })()`,
    );
  const setValue = (selector, value) =>
    evalJs(
      `(() => { const i = document.querySelector(${JSON.stringify(selector)}); if (!i) return false; Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set.call(i, ${JSON.stringify(value)}); i.dispatchEvent(new Event('input', { bubbles: true })); i.dispatchEvent(new Event('change', { bubbles: true })); return true; })()`,
    );

  await send("Page.enable");
  await send("Runtime.enable");
  await evalJs("window.confirm = () => true;");

  await loginBrowser("reader2@library.local");
  await navigate(`${APP}/admin`);
  await waitFor("location.pathname === '/catalog'", "reader redirected from /admin");
  check("Reader перенаправлен с /admin", true);

  await loginBrowser("librarian1@library.local");
  await navigate(`${APP}/admin`);
  await waitFor("location.pathname === '/catalog'", "librarian redirected from /admin");
  check("Librarian перенаправлен с /admin", true);

  await loginBrowser("admin@library.local");
  await navigate(`${APP}/admin`);
  await waitFor(
    "[...document.querySelectorAll('.dashboard__title')].some((el) => el.textContent === 'Панель управления')",
    "admin page",
  );
  check("Admin открыл /admin", true);
  const headerLink = await evalJs(
    "[...document.querySelectorAll('.site-header__link')].some((a) => a.textContent.trim() === 'Админка')",
  );
  check("В шапке есть ссылка «Админка»", headerLink === true, String(headerLink));

  for (const tab of ["Пользователи", "Книги и экземпляры", "Бронирования", "Очередь"]) {
    const found = await clickText(".dashboard__tab", tab);
    check(`Вкладка «${tab}» есть`, found === true);
  }

  // Пользователи: создание библиотекаря через форму.
  await clickText(".dashboard__tab", "Пользователи");
  await waitFor("document.querySelector('#admin-user-search')", "users section");
  await clickText(".admin-toolbar .button", "Добавить библиотекаря");
  await waitFor("document.querySelector('#admin-user-email')", "librarian form");
  await setValue("#admin-user-email", newEmail);
  await setValue("#admin-user-name", "E2E Библиотекарь");
  await setValue("#admin-user-phone", "+7 900 111-22-33");
  await setValue("#admin-user-password", E2E_PASSWORD);
  await clickText(".admin-form .button--primary", "Создать");
  await waitFor(
    `document.querySelector('.dashboard__success')?.textContent?.includes('создан')`,
    "librarian created",
  );
  check("Библиотекарь создан через форму", true);

  const rowEmail = await evalJs(
    `(() => { const row = [...document.querySelectorAll('.admin-row')].find((r) => r.textContent.includes(${JSON.stringify(newEmail)})); return row ? true : false; })()`,
  );
  check("Новый библиотекарь в списке", rowEmail === true, String(rowEmail));

  const roleChanged = await evalJs(
    `(() => { const row = [...document.querySelectorAll('.admin-row')].find((r) => r.textContent.includes(${JSON.stringify(newEmail)})); const sel = row?.querySelector('.admin-row__select'); if (!sel) return false; sel.value = 'reader'; sel.dispatchEvent(new Event('change', { bubbles: true })); return true; })()`,
  );
  await waitFor(
    `document.querySelector('.dashboard__success')?.textContent?.includes('изменена')`,
    "role changed",
  );
  const afterRole = await api("GET", `/admin/users/?search=${encodeURIComponent(newEmail)}`, admin);
  check(
    "Роль пользователя изменена на reader",
    roleChanged === true && afterRole.data.results?.[0]?.role === "reader",
    afterRole.data.results?.[0]?.role,
  );

  const blocked = await evalJs(
    `(() => { const row = [...document.querySelectorAll('.admin-row')].find((r) => r.textContent.includes(${JSON.stringify(newEmail)})); const btn = [...row.querySelectorAll('.button')].find((b) => b.textContent.trim() === 'Заблокировать'); if (!btn) return false; btn.click(); return true; })()`,
  );
  await waitFor(
    `(() => { const row = [...document.querySelectorAll('.admin-row')].find((r) => r.textContent.includes(${JSON.stringify(newEmail)})); return row?.textContent.includes('Заблокирован'); })()`,
    "user blocked",
  );
  const blockedLogin = await loginApi(newEmail, E2E_PASSWORD);
  check(
    "Заблокированный пользователь не может войти",
    blocked === true && blockedLogin.status === 401,
    String(blockedLogin.status),
  );

  await evalJs(
    `(() => { const row = [...document.querySelectorAll('.admin-row')].find((r) => r.textContent.includes(${JSON.stringify(newEmail)})); const btn = [...row.querySelectorAll('.button')].find((b) => b.textContent.trim() === 'Разблокировать'); if (!btn) return false; btn.click(); return true; })()`,
  );
  await waitFor(
    `(() => { const row = [...document.querySelectorAll('.admin-row')].find((r) => r.textContent.includes(${JSON.stringify(newEmail)})); return row?.textContent.includes('Активен'); })()`,
    "user unblocked",
  );
  check("Пользователь разблокирован через форму", true);

  // Книги: создание, экземпляр, удаление.
  await clickText(".dashboard__tab", "Книги и экземпляры");
  await waitFor(
    `[...document.querySelectorAll('.button')].some((b) => b.textContent.trim() === 'Добавить книгу')`,
    "books section",
  );
  await clickText(".admin-toolbar .button", "Добавить книгу");
  await waitFor("document.querySelector('#admin-book-title')", "book form");
  await setValue("#admin-book-title", bookTitle);
  await setValue("#admin-book-author", "E2E Автор");
  await setValue("#admin-book-genre", "E2E");
  await setValue("#admin-book-year", "2026");
  await clickText(".admin-form .button--primary", "Сохранить");
  await waitFor(
    `document.querySelector('.dashboard__success')?.textContent?.includes('добавлена')`,
    "book created",
  );
  check("Книга создана через форму", true);

  await setValue("#admin-book-search", bookTitle);
  await evalJs("document.querySelector('#admin-book-search').closest('form').requestSubmit();");
  await waitFor(
    `[...document.querySelectorAll('.admin-row__title')].some((el) => el.textContent === ${JSON.stringify(bookTitle)})`,
    "book row",
  );

  await evalJs(
    `(() => { const row = [...document.querySelectorAll('.admin-row')].find((r) => r.querySelector('.admin-row__title')?.textContent === ${JSON.stringify(bookTitle)}); [...row.querySelectorAll('.button')].find((b) => b.textContent.trim() === 'Экземпляры')?.click(); })()`,
  );
  await waitFor(
    `[...document.querySelectorAll('.admin-panel__title')].some((el) => el.textContent.includes(${JSON.stringify(bookTitle)}))`,
    "copies panel",
  );
  await clickText(".admin-panel__actions .button", "Добавить экземпляр");
  await waitFor("document.querySelector('#admin-copy-number')", "copy form");
  await setValue("#admin-copy-number", inventory);
  await evalJs("document.querySelector('.admin-copy-form').requestSubmit();");
  await waitFor(
    `document.querySelector('.dashboard__success')?.textContent?.includes('Экземпляр добавлен')`,
    "copy created",
  );
  check("Экземпляр добавлен через форму", true);

  const copyRow = await evalJs(
    `[...document.querySelectorAll('.admin-copy-row')].some((r) => r.textContent.includes(${JSON.stringify(inventory)}))`,
  );
  check("Новый экземпляр в списке", copyRow === true, String(copyRow));

  await evalJs(
    `(() => { const row = [...document.querySelectorAll('.admin-copy-row')].find((r) => r.textContent.includes(${JSON.stringify(inventory)})); [...row.querySelectorAll('.button')].find((b) => b.textContent.trim() === 'Удалить')?.click(); })()`,
  );
  await waitFor(
    `document.querySelector('.dashboard__success')?.textContent?.includes('удалён')`,
    "copy deleted",
  );
  check("Экземпляр удалён после подтверждения", true);

  await evalJs(
    `(() => { const row = [...document.querySelectorAll('.admin-row')].find((r) => r.querySelector('.admin-row__title')?.textContent === ${JSON.stringify(bookTitle)}); [...row.querySelectorAll('.button')].find((b) => b.textContent.trim() === 'Удалить')?.click(); })()`,
  );
  await waitFor(
    `document.querySelector('.dashboard__success')?.textContent?.includes('Книга') && document.querySelector('.dashboard__success')?.textContent?.includes('удалена')`,
    "book deleted",
  );
  check("Книга удалена после подтверждения", true);

  await clickText(".dashboard__tab", "Бронирования");
  await waitFor("document.querySelector('#admin-loan-status')", "loans section");
  const loansText = await evalJs("document.querySelector('.dashboard__summary')?.textContent || document.querySelector('.dashboard__empty-title')?.textContent || ''");
  check("Раздел бронирований показывает данные", Boolean(loansText), loansText);

  await clickText(".dashboard__tab", "Очередь");
  await waitFor("document.querySelector('#admin-queue-status')", "queue section");
  const queueText = await evalJs("document.querySelector('.dashboard__summary')?.textContent || document.querySelector('.dashboard__empty-title')?.textContent || ''");
  check("Раздел очереди показывает данные", Boolean(queueText), queueText);

  ws.close();
  await fetch(`http://127.0.0.1:${CDP_PORT}/json/close/${target.id}`);

  const failed = results.filter((item) => !item.ok).length;
  console.log(`\n${results.length - failed}/${results.length} проверок пройдено; user=${newEmail}; book=${bookTitle}`);
  process.exit(failed ? 1 : 0);
}

