const pages = await (await fetch("http://127.0.0.1:9222/json/list")).json();
for (const target of pages.filter((item) => item.type === "page" && item.url.startsWith("http://localhost:5173"))) {
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    ws.addEventListener("open", resolve, { once: true });
    ws.addEventListener("error", reject, { once: true });
  });
  let id = 0;
  const pending = new Map();
  ws.addEventListener("message", (event) => {
    const message = JSON.parse(event.data);
    if (message.id && pending.has(message.id)) {
      const entry = pending.get(message.id);
      pending.delete(message.id);
      message.error ? entry.reject(message.error) : entry.resolve(message.result);
    }
  });
  const send = (method, params = {}) => {
    const current = ++id;
    ws.send(JSON.stringify({ id: current, method, params }));
    return new Promise((resolve, reject) => pending.set(current, { resolve, reject }));
  };
  const evaluate = async (expression) => {
    const result = await send("Runtime.evaluate", {
      expression,
      returnByValue: true,
      awaitPromise: true,
    });
    return result.result.value;
  };
  const info = await evaluate(`(() => ({
    path: location.pathname,
    tab: [...document.querySelectorAll('.dashboard__tab--active')].map((el) => el.textContent.trim()),
    hasUsers: Boolean(document.querySelector('#admin-user-search')),
    hasBookForm: Boolean(document.querySelector('#admin-book-title')),
    hasCopies: Boolean(document.querySelector('#admin-copy-number')),
    success: document.querySelector('.dashboard__success')?.textContent || '',
    error: document.querySelector('.error-message')?.textContent || '',
    body: document.body.innerText.slice(0, 300),
  }))()`);
  console.log(JSON.stringify({ target: target.id, ...info }, null, 2));
  ws.close();
}

