import { api } from "./client";

function periodParams(dateFrom, dateTo) {
  const params = {};
  if (dateFrom) params.date_from = dateFrom;
  if (dateTo) params.date_to = dateTo;
  return params;
}

/** Сводка отчёта за период. */
export async function fetchReportSummary({ dateFrom = "", dateTo = "", signal } = {}) {
  const { data } = await api.get("/reports/summary/", {
    params: periodParams(dateFrom, dateTo),
    signal,
  });
  return data;
}

function filenameFrom(disposition, fallback) {
  const match = /filename="?([^";]+)"?/.exec(disposition || "");
  return match ? match[1] : fallback;
}

/** Скачать CSV (loans или books) с сохранением BOM от сервера. */
export async function downloadReportCsv(kind, { dateFrom = "", dateTo = "" } = {}) {
  const response = await api.get(`/reports/${kind}.csv`, {
    params: periodParams(dateFrom, dateTo),
    responseType: "blob",
  });
  const filename = filenameFrom(response.headers["content-disposition"], `${kind}.csv`);
  const url = URL.createObjectURL(response.data);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
  return filename;
}

import { api } from "./client";

/** Журнал действий с фильтрами и серверной пагинацией. */
export async function fetchLogs({
  userId = "",
  userEmail = "",
  action = "",
  dateFrom = "",
  dateTo = "",
  page = 1,
  signal,
} = {}) {
  const params = { page };
  if (userId) params.user_id = userId;
  if (userEmail) params.user_email = userEmail;
  if (action) params.action = action;
  if (dateFrom) params.date_from = dateFrom;
  if (dateTo) params.date_to = dateTo;

  const { data } = await api.get("/logs/", { params, signal });
  return data;
}

import { NavLink } from "react-router-dom";

const LINKS = [
  { to: "/admin", label: "Панель", end: true },
  { to: "/admin/reports", label: "Отчёты" },
  { to: "/admin/logs", label: "Журнал" },
];

function linkClass({ isActive }) {
  return `admin-nav__link${isActive ? " admin-nav__link--active" : ""}`;
}

/** Навигация между разделами админ-панели. */
export default function AdminNav() {
  return (
    <nav className="admin-nav" aria-label="Разделы администрирования">
      {LINKS.map((link) => (
        <NavLink key={link.to} className={linkClass} to={link.to} end={link.end}>
          {link.label}
        </NavLink>
      ))}
    </nav>
  );
}

