const CDP_PORT = 9222;
const APP = "http://localhost:5173";
const API = "http://127.0.0.1:8000/api";
const PASSWORD = "demo12345";

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const results = [];
function check(label, ok, details) {
  results.push({ label, ok });
  console.log(`${ok ? "PASS" : "FAIL"}  ${label}${details ? ` — ${details}` : ""}`);
}

async function api(method, path, token, body) {
  const headers = {};
  if (body) headers["Content-Type"] = "application/json";
  if (token) headers.Authorization = `Bearer ${token}`;
  const res = await fetch(`${API}${path}`, {
    method,
    headers,
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  return { status: res.status, data: text ? JSON.parse(text) : {} };
}

async function main() {
  const adminLogin = await api("POST", "/auth/login/", null, {
    email: "admin@library.local",
    password: PASSWORD,
  });
  const readerLogin = await api("POST", "/auth/login/", null, {
    email: "reader2@library.local",
    password: PASSWORD,
  });
  const admin = adminLogin.data.access;
  const reader = readerLogin.data.access;

  const summary = await api("GET", "/reports/summary/?date_from=2026-01-01&date_to=2026-12-31", admin);
  const logs = await api("GET", "/logs/?page=1", admin);
  const readerSummary = await api("GET", "/reports/summary/", reader);
  const readerLogs = await api("GET", "/logs/", reader);
  check("Admin получает сводку отчёта", summary.status === 200 && Boolean(summary.data.totals), String(summary.status));
  check("Сводка содержит топ и загрузку", summary.data.top_books?.length > 0 && summary.data.book_load?.length > 0, `${summary.data.top_books?.length}/${summary.data.book_load?.length}`);
  check("Admin получает журнал", logs.status === 200 && logs.data.count > 0, String(logs.data.count));
  check("Reader получает 403 на отчёт", readerSummary.status === 403, String(readerSummary.status));
  check("Reader получает 403 на журнал", readerLogs.status === 403, String(readerLogs.status));

  const target = await (await fetch(
    `http://127.0.0.1:${CDP_PORT}/json/new?${encodeURIComponent("about:blank")}`,
    { method: "PUT" },
  )).json();
  const ws = await new Promise((resolve, reject) => {
    const s = new WebSocket(target.webSocketDebuggerUrl);
    s.addEventListener("open", () => resolve(s), { once: true });
    s.addEventListener("error", reject, { once: true });
  });

  let lastId = 0;
  const pending = new Map();
  ws.addEventListener("message", (e) => {
    const m = JSON.parse(e.data);
    if (m.id && pending.has(m.id)) {
      const p = pending.get(m.id);
      pending.delete(m.id);
      m.error ? p.reject(new Error(JSON.stringify(m.error))) : p.resolve(m.result);
    }
  });
  const send = (method, params = {}) => {
    const id = ++lastId;
    ws.send(JSON.stringify({ id, method, params }));
    return new Promise((resolve, reject) => pending.set(id, { resolve, reject }));
  };
  const evalJs = async (expression) => {
    const r = await send("Runtime.evaluate", {
      expression, returnByValue: true, awaitPromise: true, userGesture: true,
    });
    if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || "eval failed");
    return r.result.value;
  };
  const waitFor = async (expr, label, timeout = 25000) => {
    const start = Date.now();
    while (Date.now() - start < timeout) {
      const v = await evalJs(expr).catch(() => false);
      if (v) return v;
      await sleep(120);
    }
    throw new Error(`timeout: ${label}`);
  };
  const navigate = async (url) => {
    await send("Page.navigate", { url });
    await waitFor("document.readyState === 'complete'", `load ${url}`);
    await waitFor("document.getElementById('root')?.children.length > 0", `render ${url}`);
  };
  const loginBrowser = async (email) => {
    await send("Storage.clearDataForOrigin", { origin: APP, storageTypes: "local_storage" });
    await navigate(`${APP}/login`);
    await evalJs(
      `(() => { const set = (sel, v) => { const i = document.querySelector(sel); Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set.call(i, v); i.dispatchEvent(new Event('input', { bubbles: true })); }; set('#login-email', ${JSON.stringify(email)}); set('#login-password', '${PASSWORD}'); document.querySelector('form').requestSubmit(); })()`,
    );
    await waitFor("location.pathname === '/catalog'", `login ${email}`);
  };

  await send("Page.enable");
  await send("Runtime.enable");

  await loginBrowser("reader2@library.local");
  await navigate(`${APP}/admin/reports`);
  await waitFor("location.pathname === '/catalog'", "reader redirected from reports");
  await navigate(`${APP}/admin/logs`);
  await waitFor("location.pathname === '/catalog'", "reader redirected from logs");
  check("Reader перенаправлен с /admin/reports и /admin/logs", true);

  await loginBrowser("admin@library.local");
  await navigate(`${APP}/admin/reports`);
  await waitFor(
    "[...document.querySelectorAll('.dashboard__title')].some((el) => el.textContent === 'Отчёты')",
    "reports page",
  );
  const cards = await evalJs("document.querySelectorAll('.stat-card').length");
  const tables = await evalJs("document.querySelectorAll('.admin-table').length");
  const periodSaved = await evalJs("Boolean(document.querySelector('#report-date-from')?.value)");
  const exportsFound = await evalJs(
    "[...document.querySelectorAll('button')].filter((b) => b.textContent.includes('.csv')).length",
  );
  check("Страница /admin/reports открыта", true);
  check("Четыре карточки событий", cards === 4, String(cards));
  check("Таблицы топа и загрузки", tables === 2, String(tables));
  check("Период заполнен по умолчанию", periodSaved === true);
  check("Кнопки экспорта CSV есть", exportsFound === 2, String(exportsFound));

  const navLinks = await evalJs("document.querySelectorAll('.admin-nav__link').length");
  check("Навигация админки из трёх разделов", navLinks === 3, String(navLinks));

  await navigate(`${APP}/admin/logs`);
  await waitFor(
    "[...document.querySelectorAll('.dashboard__title')].some((el) => el.textContent === 'Журнал действий')",
    "logs page",
  );
  const rows = await evalJs("document.querySelectorAll('.admin-table tbody tr').length");
  check("Страница /admin/logs открыта", true);
  check("В журнале есть записи", rows > 0, String(rows));

  await evalJs(
    `(() => { const sel = document.querySelector('#log-action'); sel.value = 'login'; sel.dispatchEvent(new Event('change', { bubbles: true })); })()`,
  );
  await waitFor(
    "[...document.querySelectorAll('.admin-table tbody tr')].every((r) => r.textContent.includes('Вход'))",
    "logs filtered by action",
  );
  check("Фильтр по действию работает", true);

  await ws.close();
  const failed = results.filter((r) => !r.ok);
  console.log(`\n${results.length - failed.length}/${results.length} проверок пройдено`);
  if (failed.length) process.exitCode = 1;
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

